def solve(inputs: dict) -> float:
    remainders = inputs.get("remainders")
    moduli = inputs.get("moduli")

    # Chinese Remainder Theorem
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # CRT algorithm
    x = 0
    M = 1
    for m in moduli:
        M *= m

    for rem, mod in zip(remainders, moduli):
        Mi = M // mod
        yi = mod_inverse(Mi, mod)
        x += rem * Mi * yi

    x = x % M
    return float(x)
"}

